"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useTranslations } from "next-intl";
import { TextInput } from "@/app/_components/TextInput";
import type { ProcessEvent, SeedFile } from "@/app/features/sub_dev/DevTypes";

// Live Work Surface (moonshot E) — an in-product editor over the materialized seed.
// As the candidate works, it records OBSERVED process events (which files they
// open, edit, and decision-log entries) and flushes them + the file tree to the
// session. The engine then grades the judgment we WATCHED, not a reconstructed git
// log. We observe process artifacts only — never keystrokes or the screen.

const DECISIONS_FILE = "DECISIONS.md";
const FLUSH_MS = 8000;
const EDIT_DEBOUNCE_MS = 600;

export function LiveWorkSurface({ token, seedFiles, note }: { token: string; seedFiles: SeedFile[]; note: string | null }) {
  const t = useTranslations("devApply.workSurface");
  const [files, setFiles] = useState<SeedFile[]>(() => seedFiles.map((f) => ({ ...f })));
  const [activePath, setActivePath] = useState<string>(seedFiles[0]?.path ?? "");
  const [status, setStatus] = useState<"idle" | "submitting" | "submitted" | "error">("idle");

  // Identity (UAT M9): the live-work surface is the SOLE submit path for workspace
  // cases now, so it collects who to reach — a winning evaluation with no address
  // is an unreachable candidate. Labels reuse the repo-form's `devApply` keys.
  const tApply = useTranslations("devApply");
  const [name, setName] = useState("");
  const [contact, setContact] = useState("");
  const contactValid = /\S+@\S+\.\S+/.test(contact.trim());
  const canSubmit = name.trim().length > 0 && contactValid && status !== "submitting";

  const sessionIdRef = useRef<string | null>(null);
  const startingRef = useRef(false);
  const submittingRef = useRef(false);
  const pendingRef = useRef<ProcessEvent[]>([]);
  const filesRef = useRef(files);
  // Mid-flight update (LLM-era controls #5): revealed by the SERVER via the flush
  // response once the session crosses the case's afterMinutes; rendered as a
  // stakeholder banner. The reveal moment is server-recorded in the process log.
  const [perturbation, setPerturbation] = useState<string | null>(null);
  useEffect(() => {
    // Keep the ref current for the flush callback without re-creating the interval
    // on every keystroke. Synced in an effect (not during render) per react-hooks/refs.
    filesRef.current = files;
  }, [files]);
  const editTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Lazily mint the session on first interaction — never orphan a session for a
  // visitor who only reads the brief.
  const ensureSession = useCallback(async (): Promise<string | null> => {
    if (sessionIdRef.current) return sessionIdRef.current;
    if (startingRef.current) return null;
    startingRef.current = true;
    try {
      const r = await fetch("/api/devcase/session", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token }),
      });
      if (!r.ok) return null;
      const data = (await r.json()) as { sessionId?: string; watermark?: string };
      sessionIdRef.current = data.sessionId ?? null;
      // Session watermark (LLM-era controls #4): stamp the session reference into
      // the DECISIONS log once. Innocuous per-session marker — evaluation scans
      // submissions for FOREIGN marks (a shared/relayed solution).
      if (data.watermark) {
        setFiles((prev) =>
          prev.map((f) =>
            f.path.endsWith(DECISIONS_FILE) && !f.contents.includes(data.watermark!)
              ? { ...f, contents: `${f.contents.trimEnd()}\n\nSession ref: ${data.watermark}\n` }
              : f
          )
        );
      }
      return sessionIdRef.current;
    } catch {
      return null;
    } finally {
      startingRef.current = false;
    }
  }, [token]);

  const record = useCallback(
    (kind: ProcessEvent["kind"], path?: string, size?: number) => {
      pendingRef.current.push({ t: Date.now(), kind, path, size });
      void ensureSession();
    },
    [ensureSession]
  );

  const flush = useCallback(
    async (opts?: { submit?: boolean }) => {
      const sid = await ensureSession();
      if (!sid) return;
      const batch = pendingRef.current;
      pendingRef.current = [];
      try {
        const r = await fetch(`/api/devcase/session/${sid}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ events: batch, files: filesRef.current }),
          keepalive: opts?.submit,
        });
        if (!r.ok) throw new Error("flush failed");
        // The server decides when the mid-flight update fires; the flush response
        // carries it (and keeps carrying it so a reload re-renders the banner).
        const data = (await r.json().catch(() => null)) as { perturbation?: string | null } | null;
        if (data?.perturbation) setPerturbation(data.perturbation);
      } catch {
        // Re-buffer so an unsent batch isn't lost (best-effort).
        pendingRef.current = batch.concat(pendingRef.current);
      }
    },
    [ensureSession]
  );

  useEffect(() => {
    const iv = setInterval(() => void flush(), FLUSH_MS);
    return () => {
      clearInterval(iv);
      if (editTimer.current) clearTimeout(editTimer.current);
    };
  }, [flush]);

  function selectFile(path: string) {
    if (path === activePath) return;
    setActivePath(path);
    record("open", path);
  }

  function onEdit(path: string, contents: string) {
    setFiles((prev) => prev.map((f) => (f.path === path ? { ...f, contents } : f)));
    if (editTimer.current) clearTimeout(editTimer.current);
    editTimer.current = setTimeout(() => {
      record(path.endsWith(DECISIONS_FILE) ? "decision_log" : "edit", path);
    }, EDIT_DEBOUNCE_MS);
  }

  async function submit() {
    // Synchronous in-flight guard: setStatus is async, so a fast double Enter/click
    // could dispatch two POSTs before the button visibly disables. The ref flips
    // immediately, so a second call is a no-op until this one settles; reset in the
    // finally so an error is retryable (on success the submit button is gone anyway).
    if (submittingRef.current || !canSubmit) return;
    submittingRef.current = true;
    setStatus("submitting");
    record("submit", activePath);
    try {
      await flush({ submit: true });
      const sid = sessionIdRef.current;
      if (!sid) {
        setStatus("error");
        return;
      }
      const r = await fetch(`/api/devcase/session/${sid}/submit`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ candidate: name.trim(), contact: contact.trim() }),
      }).catch(() => null);
      setStatus(r && r.ok ? "submitted" : "error");
    } finally {
      submittingRef.current = false;
    }
  }

  const active = files.find((f) => f.path === activePath) ?? files[0];

  // Captured chat channels (LLM-era controls #2/#5): assistant + stakeholder.
  // Everything flows through the platform — the dialogue is part of the submission.
  const [chatChannel, setChatChannel] = useState<"assistant" | "stakeholder">("assistant");
  const [chatMessages, setChatMessages] = useState<{ channel: string; role: "user" | "model"; text: string }[]>([]);
  const [chatInput, setChatInput] = useState("");
  const [chatState, setChatState] = useState<"idle" | "sending" | "error">("idle");

  async function sendChat() {
    const message = chatInput.trim();
    if (!message || chatState === "sending") return;
    setChatState("sending");
    setChatMessages((prev) => [...prev, { channel: chatChannel, role: "user", text: message }]);
    setChatInput("");
    try {
      const sid = await ensureSession();
      if (!sid) throw new Error("no session");
      const r = await fetch(`/api/devcase/session/${sid}/chat`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          channel: chatChannel,
          message,
          currentFile: chatChannel === "assistant" && active ? { path: active.path, contents: active.contents } : null,
        }),
      });
      if (!r.ok) throw new Error("chat failed");
      const data = (await r.json()) as { reply?: string };
      if (data.reply) setChatMessages((prev) => [...prev, { channel: chatChannel, role: "model", text: data.reply! }]);
      setChatState("idle");
    } catch {
      setChatState("error");
    }
  }

  const visibleChat = chatMessages.filter((m) => m.channel === chatChannel);

  if (status === "submitted") {
    return (
      <section className="mt-6 rounded-lg border border-emerald-200 bg-emerald-50 p-5">
        <h2 className="font-serif text-h3 text-emerald-900">{t("submittedTitle")}</h2>
        <p className="mt-1 text-sm text-emerald-800">{t("submitted")}</p>
      </section>
    );
  }

  return (
    <section className="mt-6 rounded-lg border border-stone-200 bg-white p-5 shadow-panel">
      <h2 className="font-serif text-h3 text-ink">{t("heading")}</h2>
      <p className="mt-1 max-w-prose text-sm text-steel">{t("intro")}</p>
      {note ? <p className="mt-2 text-xs text-stone-400">{note}</p> : null}

      {perturbation ? (
        <div className="mt-4 rounded-lg border border-amber-200 bg-amber-50 p-4" role="status">
          <p className="text-meta uppercase text-amber-700">{t("updateHeading")}</p>
          <p className="mt-1 text-sm text-amber-900">{perturbation}</p>
        </div>
      ) : null}

      <div className="mt-4 grid gap-3 sm:grid-cols-[180px_1fr]">
        <ul className="space-y-1">
          {files.map((f) => (
            <li key={f.path}>
              <button
                type="button"
                onClick={() => selectFile(f.path)}
                className={`w-full truncate rounded px-2 py-1 text-left font-mono text-xs ${
                  f.path === active?.path ? "bg-stone-900 text-white" : "text-ink hover:bg-stone-100"
                }`}
                title={f.path}
              >
                {f.path}
              </button>
            </li>
          ))}
        </ul>
        <textarea
          value={active?.contents ?? ""}
          onChange={(e) => active && onEdit(active.path, e.target.value)}
          onPaste={(e) => {
            // Record paste MAGNITUDE (char count) only — not the content. A single
            // large bulk paste into the watched editor is the in-product
            // paste-from-LLM tell the authenticity scorer now penalizes.
            const n = (e.clipboardData?.getData("text") ?? "").length;
            if (active && n > 0) record("paste", active.path, n);
          }}
          spellCheck={false}
          className="focus-ring h-80 w-full resize-y rounded-md border border-stone-200 bg-stone-50 p-3 font-mono text-xs leading-relaxed text-ink caret-coral"
          aria-label={active?.path ?? "editor"}
        />
      </div>

      <div className="mt-5 rounded-lg border border-stone-200 bg-paper/40 p-4">
        <h3 className="text-sm font-semibold text-ink">{t("chatHeading")}</h3>
        <p className="mt-1 max-w-prose text-xs text-steel">{t("chatIntro")}</p>
        <div className="mt-3 flex gap-1" role="tablist" aria-label={t("chatHeading")}>
          {(["assistant", "stakeholder"] as const).map((ch) => (
            <button
              key={ch}
              type="button"
              role="tab"
              aria-selected={chatChannel === ch}
              onClick={() => setChatChannel(ch)}
              className={`rounded px-3 py-1 text-xs font-medium ${
                chatChannel === ch ? "bg-stone-900 text-white" : "text-ink hover:bg-stone-100"
              }`}
            >
              {ch === "assistant" ? t("tabAssistant") : t("tabStakeholder")}
            </button>
          ))}
        </div>
        {visibleChat.length > 0 ? (
          <ul className="mt-3 max-h-56 space-y-2 overflow-y-auto">
            {visibleChat.map((m, i) => (
              <li
                key={i}
                className={`max-w-prose whitespace-pre-wrap rounded-md px-3 py-2 text-xs leading-relaxed ${
                  m.role === "user" ? "ml-auto bg-stone-900 text-white" : "bg-white text-ink shadow-panel"
                }`}
              >
                {m.text}
              </li>
            ))}
          </ul>
        ) : null}
        <div className="mt-3 flex gap-2">
          <TextInput
            value={chatInput}
            onChange={(e) => setChatInput(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                void sendChat();
              }
            }}
            placeholder={chatChannel === "assistant" ? t("chatPlaceholderAssistant") : t("chatPlaceholderStakeholder")}
            className="flex-1"
            aria-label={t("chatHeading")}
          />
          <button
            type="button"
            onClick={() => void sendChat()}
            disabled={chatState === "sending" || chatInput.trim().length === 0}
            className="rounded-md bg-stone-900 px-3 py-2 text-xs font-medium text-white hover:bg-stone-800 disabled:cursor-not-allowed disabled:opacity-60"
          >
            {chatState === "sending" ? t("chatSending") : t("chatSend")}
          </button>
        </div>
        {chatState === "error" ? <p className="mt-2 text-xs text-red-700">{t("chatError")}</p> : null}
      </div>

      <div className="mt-4 grid gap-3 sm:grid-cols-2">
        <label className="block text-sm font-medium text-ink">
          {tApply("fieldName")} <span className="text-coral">*</span>
          <TextInput value={name} onChange={(e) => setName(e.target.value)} className="mt-1" />
        </label>
        <label className="block text-sm font-medium text-ink">
          {tApply("fieldContact")} <span className="text-coral">*</span>
          <TextInput
            type="email"
            value={contact}
            onChange={(e) => setContact(e.target.value)}
            placeholder={tApply("fieldContactPlaceholder")}
            className="mt-1"
          />
          <span className="mt-1 block text-xs font-normal text-steel">{tApply("fieldContactHint")}</span>
        </label>
      </div>
      <div className="mt-4 flex items-center gap-3">
        <button
          type="button"
          onClick={submit}
          disabled={!canSubmit}
          className="rounded-md bg-stone-900 px-4 py-2 text-sm font-medium text-white hover:bg-stone-800 disabled:cursor-not-allowed disabled:opacity-60"
        >
          {status === "submitting" ? t("submitting") : t("submit")}
        </button>
        {status === "error" ? <span className="text-sm text-red-700">{t("error")}</span> : null}
      </div>
    </section>
  );
}

import { NextResponse } from "next/server";
import { countRecentDevSessionsForToken, devSessionWatermark, getPostingByToken, startDevSession } from "@/app/_lib/db";
import { jsonError } from "@/app/_lib/api-response";

// bug-ui-scan-2026-07-09 (dev-submissions-live-work-surface #2): a per-token/day session
// throttle. Apply tokens are shareable public links, so an unauthenticated holder could
// mint unbounded sessions (each then flushing events) — a cheap storage-exhaustion vector.
// The cap is generous vs. legitimate use: one posting rarely sees this many genuine live
// starts in a day, so real candidates are never blocked.
const SESSION_WINDOW_MS = 24 * 60 * 60 * 1000;
export const MAX_SESSIONS_PER_TOKEN_DAY = 50;

// Live Work Surface (moonshot E) — start an in-product work session for a dev-case
// apply token. Validates the token maps to an OPEN posting (don't orphan sessions
// against a closed/missing posting), then mints a session.
export async function POST(request: Request) {
  try {
    const body = (await request.json().catch(() => ({}))) as { token?: unknown; candidateRef?: unknown };
    const token = typeof body.token === "string" ? body.token.trim() : "";
    if (!token) return NextResponse.json({ error: "token is required" }, { status: 400 });
    const posting = getPostingByToken(token);
    if (!posting || posting.status === "closed") {
      return NextResponse.json({ error: "This case is not accepting submissions." }, { status: 404 });
    }
    // Per-token/day throttle (bug-ui-scan-2026-07-09 #2): reject once a token has minted
    // its daily quota of sessions, so a leaked link can't amplify into unbounded rows.
    const since = new Date(Date.now() - SESSION_WINDOW_MS).toISOString();
    if (countRecentDevSessionsForToken(token, since) >= MAX_SESSIONS_PER_TOKEN_DAY) {
      return NextResponse.json({ error: "Too many sessions started for this case. Try again later." }, { status: 429 });
    }
    const candidateRef = typeof body.candidateRef === "string" ? body.candidateRef.trim() || null : null;
    const session = startDevSession({ token, candidateRef });
    // LLM-era controls #4 — the per-session watermark. The work surface stamps it
    // into the DECISIONS log as an innocuous session reference; evaluation scans
    // submissions for FOREIGN marks (a circulated/relayed solution). Derived, never
    // stored; disclosing the candidate's own mark to them is fine — absence is a
    // mild note, a foreign mark is the decisive tell.
    return NextResponse.json({ sessionId: session.id, watermark: devSessionWatermark(session.id) });
  } catch (error) {
    return jsonError(error, "Failed to start the work session.");
  }
}

import { NextResponse } from "next/server";
import {
  appendDevSessionEvents,
  getDevCase,
  getDevSession,
  getDevSessionEvents,
  getPostingByToken,
  saveDevSessionFiles,
} from "@/app/_lib/db";
import { jsonError } from "@/app/_lib/api-response";


// Live Work Surface (moonshot E) — append observed events + save the (editable)
// seed tree for an active session. Hand-rolled boundary coercion + bounds (the
// payload is candidate-controlled): drop unknown event kinds, cap counts/size.
// "paste" carries the paste MAGNITUDE (`size`, char count) — the in-product
// bulk-paste authenticity tell (devcase-authenticity PASTE_BULK_CHARS). Bug-ui-scan
// 2026-07-09 #1: it was previously OMITTED from this allow-list (and `size` dropped
// by the map/DB), so the -65 anti-ghostwriting penalty could never fire.
const KINDS = new Set(["open", "edit", "decision_log", "submit", "paste"]);
const MAX_EVENTS = 500; // per flush
const MAX_FILES = 50;
const MAX_FILE_BYTES = 256 * 1024;

export async function POST(request: Request, { params }: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await params;
    const session = getDevSession(id);
    if (!session) return NextResponse.json({ error: "session not found" }, { status: 404 });
    if (session.status !== "active") return NextResponse.json({ error: "session already submitted" }, { status: 409 });

    const body = (await request.json().catch(() => ({}))) as { events?: unknown; files?: unknown };

    let seq = 0;
    if (Array.isArray(body.events)) {
      const events = body.events
        .slice(0, MAX_EVENTS)
        .filter((e): e is Record<string, unknown> => !!e && typeof e === "object")
        .filter((e) => KINDS.has(String(e.kind)))
        .map((e) => ({
          t: Number(e.t) || 0,
          kind: String(e.kind),
          path: typeof e.path === "string" ? e.path : null,
          // Carry the paste MAGNITUDE (char count) through to the DB so the observed
          // bulk-paste authenticity penalty can fire. Candidate-controlled, so coerce
          // to a finite number (never the raw shape); null for non-paste kinds.
          size: Number.isFinite(Number(e.size)) ? Number(e.size) : null,
        }));
      seq = appendDevSessionEvents(id, events);
    }

    if (Array.isArray(body.files)) {
      const files = body.files
        .filter((f): f is Record<string, unknown> => !!f && typeof f === "object" && typeof f.path === "string")
        .slice(0, MAX_FILES)
        .map((f) => ({ path: String(f.path), contents: String(f.contents ?? "").slice(0, MAX_FILE_BYTES) }));
      saveDevSessionFiles(id, files);
    }

    // Mid-flight update reveal (LLM-era controls #5): once the session is older than
    // the case's afterMinutes, serve the requirement change with this flush response
    // and record the reveal SERVER-SIDE as a chained "perturbation" event (clients
    // can't submit that kind — see KINDS above — so the reveal moment is trustworthy).
    // Already-fired sessions keep receiving the text so a reload re-renders the banner.
    let perturbation: string | null = null;
    const kase = session.token ? (getDevCase(getPostingByToken(session.token)?.caseId ?? "")?.case as
      | { midFlightUpdate?: { afterMinutes?: number; update?: string } }
      | null) : null;
    const mfu = kase?.midFlightUpdate;
    if (mfu?.update && typeof mfu.afterMinutes === "number") {
      const fired = getDevSessionEvents(id).some((e) => e.kind === "perturbation");
      const due = Date.now() - Date.parse(session.createdAt) >= mfu.afterMinutes * 60_000;
      if (fired || due) {
        if (!fired) appendDevSessionEvents(id, [{ t: Date.now(), kind: "perturbation", path: null }]);
        perturbation = mfu.update;
      }
    }

    return NextResponse.json({ ok: true, seq, perturbation });
  } catch (error) {
    return jsonError(error, "Failed to save the work session.");
  }
}

import { createHash } from "node:crypto";
import { coerceOutboxStatus, type OutboxStatus } from "../comms-status";
import { randomId } from "../random-id";
import type { DevNeed } from "../devcase-run";
import { ensureDb, safeRowParse } from "./core";
import { DEFAULT_WORKSPACE_ID } from "./workspaces";

// ---- Dev extension — approved case scenarios (Phase D3) -------------------

export type DevCaseRecord = {
  id: string;
  title: string | null;
  roleTitle: string | null;
  seniority: string | null;
  need: unknown;
  analysis: unknown;
  role: unknown;
  case: unknown;
  // The role's AI-interview scenario generated from the approved case
  // (devcase/interview_scenario.py) — null until the lifecycle generates it.
  scenario: unknown;
  // The case's materialized seed ({files: [{path, contents}], note}) — null
  // until the lifecycle materializes it (devcase/seed_materializer.py).
  seed: unknown;
  status: string;
  createdAt: string;
};

type DevCaseRow = {
  id: string;
  title: string | null;
  role_title: string | null;
  seniority: string | null;
  need_json: string | null;
  analysis_json: string | null;
  role_json: string | null;
  case_json: string | null;
  scenario_json: string | null;
  seed_json: string | null;
  status: string;
  created_at: string;
};

function rowToDevCase(r: DevCaseRow): DevCaseRecord {
  return {
    id: r.id,
    title: r.title,
    roleTitle: r.role_title,
    seniority: r.seniority,
    need: safeRowParse(r.need_json, "devCase.need", r.id),
    analysis: safeRowParse(r.analysis_json, "devCase.analysis", r.id),
    role: safeRowParse(r.role_json, "devCase.role", r.id),
    case: safeRowParse(r.case_json, "devCase.case", r.id),
    scenario: safeRowParse(r.scenario_json, "devCase.scenario", r.id),
    seed: safeRowParse(r.seed_json, "devCase.seed", r.id),
    status: r.status,
    createdAt: r.created_at,
  };
}

/** Persist the case-designed interview scenario on its dev case (one per role). */
export function saveDevCaseScenario(id: string, scenario: unknown): void {
  const db = ensureDb();
  db.prepare(`UPDATE dev_cases SET scenario_json = ? WHERE id = ?`).run(JSON.stringify(scenario ?? null), id);
}

/** Persist the materialized seed (the concrete starter file tree) on its dev case. */
export function saveDevCaseSeed(id: string, seed: unknown): void {
  const db = ensureDb();
  db.prepare(`UPDATE dev_cases SET seed_json = ? WHERE id = ?`).run(JSON.stringify(seed ?? null), id);
}

// FREEZE-AT-PUBLISH (bug-ui-scan-2026-07-09 #1). The seed + interview scenario are
// the candidate-facing assignment; once a posting's token is live, two candidates on
// the SAME case must be handed the IDENTICAL materials (comparability + audit trail).
// These compare-and-set writes fill the column ONLY WHEN IT IS STILL ABSENT
// (`WHERE ... IS NULL`) — SQLite serializes the UPDATE, so the FIRST materialization
// wins and every later attempt (a lifecycle resume re-running the `approved` handler)
// is a no-op that leaves the live seed untouched, instead of the old unconditional
// UPDATE that overwrote it in place with a fresh (non-deterministic LLM) render.
// Returns whether THIS call performed the write (false ⇒ already frozen).

/** Freeze the interview scenario: set it only if the case has none yet. */
export function saveDevCaseScenarioIfAbsent(id: string, scenario: unknown): boolean {
  const db = ensureDb();
  return (
    db
      .prepare(`UPDATE dev_cases SET scenario_json = ? WHERE id = ? AND scenario_json IS NULL`)
      .run(JSON.stringify(scenario ?? null), id).changes > 0
  );
}

/** Freeze the materialized seed: set it only if the case has none yet. */
export function saveDevCaseSeedIfAbsent(id: string, seed: unknown): boolean {
  const db = ensureDb();
  return (
    db
      .prepare(`UPDATE dev_cases SET seed_json = ? WHERE id = ? AND seed_json IS NULL`)
      .run(JSON.stringify(seed ?? null), id).changes > 0
  );
}

export function saveDevCase(
  input: {
    need: unknown;
    analysis: unknown;
    role: { title?: string; seniority?: string } & Record<string, unknown>;
